function pickHit(pick, result) {
  if (result === "Push") return "push";
  if (result === "Yes") return "hit";
  if (result === "No") return "miss";
  return null;
}

function overUnderHit(pick, actual) {
  if (!pick || !actual) return null;
  const isOverPick = / O\d/.test(pick) || /^O\d/.test(pick);
  const isUnderPick = / U\d/.test(pick) || /^U\d/.test(pick);
  if (isOverPick) return actual === "Over" ? "hit" : "miss";
  if (isUnderPick) return actual === "Under" ? "hit" : "miss";
  return null;
}

function historyForPlayer(name) {
  return HISTORY.filter((r) => r.name === name).sort((a, b) => a.weekNum - b.weekNum);
}

function allWeeks() {
  const seen = new Map();
  for (const r of HISTORY) seen.set(r.weekNum, r.week);
  return [...seen.entries()].sort((a, b) => a[0] - b[0]).map(([, label]) => label);
}

function historyForWeek(week) {
  return HISTORY.filter((r) => r.week === week);
}
